from mobile_sam import build_sam_vit_t
import torch

model = build_sam_vit_t(checkpoint=None)

state_dict = torch.load('/tmp/torch/hub/checkpoints/mobile_sam.pt', map_location='cpu')

# Check model parameter shapes vs checkpoint
model_sd = model.state_dict()
mismatches = []

for key in model_sd.keys():
